import streamlit as st
import pandas as pd

st.set_page_config(page_title="eLEKSYON '28 Dashboard", layout="wide")
st.title("🗳️ eLEKSYON '28: Philippine Voter Turnout Prediction System")

# Load data generated by eleksyon28_analysis.py
df_hist = pd.read_csv("ph_voter_turnout_dataset.csv")
df_city = pd.read_csv("predictions_2028_by_city.csv")
df_region = pd.read_csv("predictions_2028_by_region.csv")

# Sidebar Geographical Filter (Feature 3)
st.sidebar.header("Geographical Filter")
selected_region = st.sidebar.selectbox("Select Region", ["All Regions"] + sorted(df_city["region"].unique()))

if selected_region != "All Regions":
    filtered_city = df_city[df_city["region"] == selected_region]
    filtered_hist = df_hist[df_hist["region"] == selected_region]
else:
    filtered_city = df_city
    filtered_hist = df_hist

# Top KPI Metrics
col1, col2, col3 = st.columns(3)
col1.metric("2025 Avg Turnout", f"{filtered_city['Turnout_2025_Pct'].mean():.2f}%")
col2.metric("2028 Predicted Avg Turnout", f"{filtered_city['Predicted_2028_Turnout_Pct'].mean():.2f}%")
col3.metric("Cities / Municipalities Tracked", len(filtered_city))

# Charts & Tables
st.subheader("📊 Historical Turnout Trend (2004–2025)")
trend = filtered_hist.groupby("election_year")["actual_voter_turnout_pct"].mean()
st.line_chart(trend)

col_left, col_right = st.columns(2)
with col_left:
    st.subheader("🗺️ 2028 Turnout Predictions by Region")
    st.dataframe(df_region, use_container_width=True)

with col_right:
    st.subheader("🏙️ 2028 Turnout Predictions by City/Municipality")
    st.dataframe(filtered_city, use_container_width=True)

# Linear Algebra Model Plots
st.subheader("📐 Linear Algebra & PCA Diagnostics")
c1, c2, c3 = st.columns(3)
c1.image("scree_plot.png", caption="PCA Scree Plot")
c2.image("pca_projection.png", caption="PC1 vs PC2 Projection")
c3.image("predicted_vs_actual.png", caption="OLS Predicted vs Actual")